// client: hand-built page (P59 course editor); not generated by tools/dc2jsx.ts.
//
// Types mirror the backend admin API (backend:docs/API-CONTRACT.md "Admin: courses", and the
// courses / course_modules / course_units / course_blocks / course_assessments /
// assessment_questions tables) so the mock store in ./store.ts can be swapped for fetch calls.
// Where the design needs something the backend does not have yet, the field is marked
// "client-only" and listed in docs/CLIENT-NOTES.md under "Backend gaps".

export type I18n = { en: string; ar: string }
export type CourseStatus = 'draft' | 'published' | 'archived'
export type Level = 'beginner' | 'intermediate' | 'advanced'

export type BlockType =
  | 'youtube'
  | 'text'
  | 'case_study'
  | 'quotes'
  | 'audio'
  | 'resources'
  | 'scorm'
  | 'youtube_playlist'
  | 'action_plan'
  | 'survey'
  | 'quiz_blocking'

export interface PointsConfig {
  unit: number
  module: number
  course: number
  assessmentPass: number
}

export interface MicrositeLink {
  id: string
  mandatory: boolean
}

/** `courses` row. */
export interface Course {
  id: string
  slug: string
  title: I18n
  description: I18n
  overview: I18n
  imageUrl: string
  categories: string[]
  level: Level
  durationMin: number
  status: CourseStatus
  sequential: boolean
  certificateEnabled: boolean
  externalCertificate: boolean
  comingSoon: boolean
  isCertProgramme: boolean
  pointsConfig: PointsConfig
  microsites: MicrositeLink[]
}

/** PUT /api/admin/courses/{id}/certificate. `showSerial` is client-only. */
export interface CertificateSettings {
  signatureName: string
  signatureTitle: string
  showSerial: boolean
}

export interface ResourceFile {
  name: string
  ext: string
  size: string
  color: string
}
export interface PlaylistVideo {
  title: I18n
  videoId: string
  duration: string
}
export interface Quote {
  text: I18n
  author: I18n
}
export type SurveyQuestionType = 'single' | 'scale' | 'open'

/** `course_blocks.payload`: every block type keeps its own fields here, plus a bilingual title. */
export interface BlockPayload {
  title: I18n
  videoUrl?: string
  mustWatch?: boolean
  body?: I18n
  scenario?: I18n
  reflection?: I18n
  quotes?: Quote[]
  audioMeta?: string
  transcript?: I18n
  files?: ResourceFile[]
  scormMeta?: string
  launchFile?: string
  completionRule?: 'completed' | 'passed'
  videos?: PlaylistVideo[]
  intro?: I18n
  planQuestions?: { text: I18n; limit: number }[]
  allowPdf?: boolean
  surveyQuestions?: { text: I18n; type: SurveyQuestionType }[]
  /** quiz_blocking blocks point at a unit-level `course_assessments` row. */
  assessmentId?: string
}

export interface Block {
  id: string
  unitId: string
  type: BlockType
  order: number
  required: boolean
  payload: BlockPayload
}

export interface UnitNode {
  id: string
  moduleId: string
  title: I18n
  order: number
  durationMin: number | null
  blocks: Block[]
}

export interface ModuleNode {
  id: string
  title: I18n
  order: number
  units: UnitNode[]
}

export type QuestionType = 'multiple_choice' | 'true_false' | 'open_text' | 'sorting'

export interface QuestionOption {
  id: string
  text: I18n
  correct: boolean
}

/** `assessment_questions` row. */
export interface Question {
  id: string
  type: QuestionType
  text: I18n
  options: QuestionOption[]
  points: number
  order: number
}

export type AssessmentType = 'quiz_blocking' | 'quiz_non_blocking' | 'survey'
/**
 * pre: shown before the modules (client-only, no backend column yet)
 * post: the course's final assessment (`is_final`)
 * unit: attached to a unit (`unit_id`), reached from a quiz block
 */
export type AssessmentKind = 'pre' | 'post' | 'unit'

/** `course_assessments` row plus its current questions. */
export interface Assessment {
  id: string
  kind: AssessmentKind
  unitId: string | null
  title: I18n
  type: AssessmentType
  passMark: number
  attemptsAllowed: number
  timeLimitMin: number | null
  shuffle: boolean
  /** client-only */
  showAnswers: boolean
  isFinal: boolean
  version: number
  hasAttempts: boolean
  questions: Question[]
}

/** GET /api/admin/courses/{id}. */
export interface CourseTree {
  course: Course
  modules: ModuleNode[]
  assessments: Assessment[]
  certificate: CertificateSettings
}

export type AssessmentInput = Omit<Assessment, 'id' | 'version' | 'hasAttempts' | 'questions'>
export type QuestionInput = Omit<Question, 'id' | 'order'>
export type BlockInput = Pick<Block, 'type' | 'required' | 'payload'>

/** The admin API surface the page calls. The mock store implements it; the merge swaps it for HTTP. */
export interface CourseAdminApi {
  updateCourse(patch: Partial<Course>): void
  publish(): void
  unpublish(): void
  archive(): void
  updateCertificate(patch: Partial<CertificateSettings>): void
  createModule(title: I18n): string
  updateModule(id: string, title: I18n): void
  deleteModule(id: string): void
  reorderModules(ids: string[]): void
  createUnit(moduleId: string, input: { title: I18n; durationMin: number | null }): string
  updateUnit(id: string, input: { title: I18n; durationMin: number | null }): void
  deleteUnit(id: string): void
  reorderUnits(moduleId: string, ids: string[]): void
  createBlock(unitId: string, input: BlockInput): string
  updateBlock(id: string, input: BlockInput): void
  deleteBlock(id: string): void
  reorderBlocks(unitId: string, ids: string[]): void
  createAssessment(input: AssessmentInput): string
  updateAssessment(id: string, input: AssessmentInput): void
  deleteAssessment(id: string): void
  createQuestion(assessmentId: string, input: QuestionInput): string
  updateQuestion(assessmentId: string, id: string, input: QuestionInput): void
  deleteQuestion(assessmentId: string, id: string): void
  reorderQuestions(assessmentId: string, ids: string[]): void
}
